import React, { useState, useEffect, useRef } from 'react';

interface LandingPageProps {
  onSelectView: (view: 'cli' | 'gui') => void;
}

const LandingPage: React.FC<LandingPageProps> = ({ onSelectView }) => {
  const [photoUrl, setPhotoUrl] = useState<string | null>(null);
  const [bio, setBio] = useState<string>(
    "I am a Computer Science major at Strathmore University, deeply passionate about cybersecurity, distributed systems, software development, and AI/ML. Outside of academics, I'm an avid sportsman, actively involved in rugby and hitting the gym. My defining characteristic is grit; you could say it's my middle name."
  );

  const handlePhotoUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPhotoUrl(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="landing-container">
      <div className="boot-screen">
        <p>BIOS Version: 2.1.0</p>
        <p>Copyright (C) 2025 Daryn Ongera. All Rights Reserved.</p>
        <p>CPU: Intel(R) Core(TM) i9-10900K CPU @ 3.70GHz</p>
        <p>Memory Test: 65536MB OK</p>
        <p>Initializing USB Controllers... Done.</p>
        <p>Detecting Hard Drives... Done.</p>
        <p>Loading Operating System...</p>
        <p>Welcome to Daryn Ongera's Portfolio</p>
        <p></p>

        <div style={{ display: 'flex', alignItems: 'center', marginBottom: '20px', border: '1px solid #00ff00', padding: '10px' }}>
          <div style={{ marginRight: '20px' }}>
            {photoUrl ? (
              <img src={photoUrl} alt="Profile" style={{ width: '150px', height: '150px', objectFit: 'cover', border: '2px solid #00ff00' }} />
            ) : (
              <div style={{ width: '150px', height: '150px', border: '2px dashed #00ff00', display: 'flex', justifyContent: 'center', alignItems: 'center', color: '#00ff00' }}>
                No Photo
              </div>
            )}
            <input type="file" accept="image/*" onChange={handlePhotoUpload} style={{ marginTop: '10px', color: '#00ff00' }} />
          </div>
          <div style={{ flexGrow: 1, color: '#00ff00' }}>
            <h2 style={{ color: '#00ff00' }}>About Me</h2>
            <p>{bio}</p>
          </div>
        </div>

        <p>Please select an interface:</p>
        <div className="choice-container">
          <div className="landing-box" onClick={() => onSelectView('cli')}>
            <h1>CLI</h1>
            <p>Launch Command Line Interface</p>
          </div>
          <div className="landing-box" onClick={() => onSelectView('gui')}>
            <h1>GUI</h1>
            <p>Explore Graphical User Interface</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LandingPage;
